macro_rules! BIT_MASK {
($nr:expr) => {
UL!() << ($nr) % 64
};
}

macro_rules! BIT_ULL {
($nr:expr) => {
ULL!() << $nr
};
}

macro_rules! BIT_WORD {
($nr:expr) => {
($nr) / 64
};
}

macro_rules! BIT {
($nr:expr) => {
UL!() << $nr
};
}

macro_rules! BIT__2 {
($nr:expr) => {
UL!() << (($nr) as u32)
};
}

macro_rules! BIT__3 {
($nr:expr) => {
UL!() << (($nr) as i32)
};
}

macro_rules! BUGFLAG_TAINT {
($taint:expr) => {
($taint) << 8i32
};
}

/// BUILD_BUG_ON_INVALID() permits the compiler to check the validity of the
/// expression but avoids the generation of any code, even if that expression
/// has side-effects.
macro_rules! BUILD_BUG_ON_INVALID {
() => {
};
}

macro_rules! DBM_TO_MBM {
($gain:expr) => {
$gain.wrapping_mul(100)
};
}

macro_rules! DEBUG_NET_WARN_ON_ONCE {
() => {
BUILD_BUG_ON_INVALID!();
};
}

macro_rules! FILL_IN_MESH_PARAM_IF_SET__5 {
($tb:expr, $cfg:expr, $param:ident, $mask:expr, $attr:expr) => {
loop {
if !$tb[($attr) as usize].is_null() {
unsafe {
(*$cfg).$param = nla_get_s32($tb[($attr) as usize] as *const nlattr);
}
let __v: u32 = $mask;
let __v2: u32 = ((__v as u64) | BIT!($attr.wrapping_sub(1))) as u32;
$mask = __v2;
}
if true {
break;
}
}
};
}

