// nla_type (16 bits)
// | N | O | Attribute Type                |
// N := Carries nested attributes
// O := Payload stored in network byte order
//
// Note: The N and O flag are mutually exclusive.
fn nlmsg_hdr(skb: *const sk_buff) -> *mut nlmsghdr {
(unsafe { (*skb).data }) as *mut nlmsghdr
}

