#[derive(Clone, Copy)]
union __SlateRecord_cfg80211_h_3595 {
    band_pref: u32,
    adjust: cfg80211_bss_select_adjust,
}


// Always use this macro, this allows later putting the
// message into a separate section or such for things
// like translation or listing all possible messages.
// If string formatting is needed use NL_SET_ERR_MSG_FMT.
// We splice fmt with %s at each end even in the snprintf so that both calls
// can use the same string constant, avoiding its duplication in .ro
fn nl_set_extack_cookie_u64(extack: *mut netlink_ext_ack, mut cookie: u64) {
if extack.is_null() {
return;
}
loop {
if ((const { core::mem::size_of::<[u8; 8]>() }) as u64) < ((const { core::mem::size_of::<u64>() }) as u64) {
unsafe { __compiletime_assert_706() };
unsafe { core::hint::unreachable_unchecked() };
}
if true {
break;
}
}
unsafe { memcpy(((*extack).cookie.as_mut_ptr() as *mut u8) as *mut (), core::ptr::addr_of_mut!(cookie) as *const (), core::mem::size_of::<u64>() as u64) };
unsafe {
(*extack).cookie_len = core::mem::size_of::<u64>() as u8;
}
}

